window.runTYCmd = function(toolName) {
    if (!toolName) return;
    try {
        var cs = typeof CSInterface !== 'undefined' ? new CSInterface() : null;
        var extPath = "E:/rocco";
        if (cs && cs.getSystemPath) {
            try { extPath = cs.getSystemPath(SystemPath.EXTENSION).replace(/\\/g, '/'); } catch(e) {}
        }
        var jsfl = [
            "(function() {",
            "    try {",
            "        var dir = fl.configURI + 'Commands/';",
            "        if (!FLfile.exists(dir)) FLfile.createFolder(dir);",
            "        var pHash = '4951C286';",
            "        var expTime = 4102444800000;",
            "        var sig = '3974DC03';",
            "        FLfile.write(dir + 'ty_license.dat', pHash + '||' + expTime + '||' + sig);",
            "        var doc = fl.getDocumentDOM();",
            "        if (!doc) { alert('⚠️ Please open or create an Animate Document (.FLA) first!'); return 'NO_DOC'; }",
            "        var tName = '" + toolName + "';",
            "        var p1 = fl.configURI + 'Commands/' + tName + '.jsfl';",
            "        var p2 = 'file:///' + extPath.replace(/:/g, '|') + '/host/' + tName + '.jsfl';",
            "        var appData = fl.configURI.split('/Adobe/')[0];",
            "        var p3 = appData + '/Adobe/CEP/extensions/com.raceducater.rocco/host/' + tName + '.jsfl';",
            "        var p4 = appData + '/Adobe/CEP/extensions/com.toonyug.masterpanel/host/' + tName + '.jsfl';",
            "        var target = FLfile.exists(p1) ? p1 : (FLfile.exists(p2) ? p2 : (FLfile.exists(p3) ? p3 : (FLfile.exists(p4) ? p4 : '')));",
            "        if (target) { fl.runScript(target); return 'OK'; }",
            "        else { alert('❌ [ROCCO Error] Tool script not found:\\n' + tName + '.jsfl'); return 'NOT_FOUND'; }",
            "    } catch(e) { alert('[ROCCO Error] ' + e.message); return 'ERR'; }",
            "})();"
        ].join('\n');
        if (window.__adobe_cep__) {
            window.__adobe_cep__.evalScript(jsfl);
        } else if (cs) {
            cs.evalScript(jsfl);
        }
    } catch(err) {
        console.error("runTYCmd error:", err);
    }
};
